/// The only Switchboard program and queue this build trusts
/// (`--features devnet` for devnet). A randomness account on any other queue
/// would be served by oracles of the queue owner's choosing.
#[cfg(feature = "devnet")]
pub const SWITCHBOARD_PROGRAM_ID: Pubkey = SWITCHBOARD_ON_DEMAND_DEVNET;
#[cfg(not(feature = "devnet"))]
pub const SWITCHBOARD_PROGRAM_ID: Pubkey = SWITCHBOARD_ON_DEMAND_MAINNET;
#[cfg(feature = "devnet")]
